    PageFrom: pageFrom,
    PageTo: pageTo,

    PartPages: partPages,
    SourcePages: totalPages,

    FirstPdfIndex:
      pageIndices[0],

    LastPdfIndex:
      pageIndices[pageIndices.length - 1],

    SourceBytes:
      sourceBuffer.length,

    PartBytes:
      outputBuffer.length
  },

  binary: {
    data: binaryData
  }
}];

