parameters.jsCode:
/**
 * n8n Code-Node: requiresForcedOcr?
 *
 * Aufgaben:
 * 1. Qualität der Docling-Textextraktion bewerten
 * 2. requiresForcedOcr setzen
 * 3. Original-PDF aus "HTTP - fetch PDF" wieder anhängen
 */

const CONFIG = {
  minimumCharacters: 80,
  minimumAlphanumericRatio: 0.52,
  maximumSuspiciousRatio: 0.10,
  maximumSymbolTokenRatio: 0.25,
  minimumWordCoverage: 0.30,
  fallbackScoreThreshold: 3,
};

function firstNonEmpty(values) {
  for (const value of values) {
    if (
      typeof value === 'string' &&
      value.trim() !== ''
    ) {
      return value;
    }
  }

  return '';
}

function decodeBasicHtmlEntities(text) {
  return text
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&nbsp;/gi, ' ');
}

function removeMarkdownStructure(text) {
  return text
    // Bilder und Kommentare entfernen
    .replace(/<!--[\s\S]*?-->/g, ' ')

    // Markdown-Tabellentrennlinien entfernen
    .replace(
      /^\s*\|?(?:\s*:?-{3,}:?\s*\|)+\s*$/gm,
      ' ',
    )

    // Markdown-Strukturzeichen entfernen
    .replace(/[|#*_`~]/g, ' ')

    // Leerzeichen vereinheitlichen
    .replace(/\s+/g, ' ')
    .trim();
}

function round(value) {
  return Math.round(value * 1000) / 1000;
}

function assessTextQuality(json) {
  const rawText = firstNonEmpty([
    json?.document?.md_content,
    json?.document?.text_content,
    json?.md_content,
    json?.text_content,
    json?.text,
  ]);

  if (!rawText) {
    return {
      requiresForcedOcr: true,
      score: 10,
      reasons: ['no_text_returned'],
      metrics: {
        rawCharacters: 0,
        evaluatedCharacters: 0,
      },
    };
  }

  const decodedText =
    decodeBasicHtmlEntities(rawText);

  const evaluatedText =
    removeMarkdownStructure(decodedText);

  const compactText =
    evaluatedText.replace(/\s/g, '');

  const characterCount = compactText.length;

  if (characterCount === 0) {
    return {
      requiresForcedOcr: true,
      score: 10,
      reasons: ['no_evaluable_text'],
      metrics: {
        rawCharacters: rawText.length,
        evaluatedCharacters: 0,
      },
    };
  }

  const alphanumericCount =
    (
      compactText.match(
        /[\p{L}\p{N}]/gu,
      ) || []
    ).length;

  const letterCount =
    (
      compactText.match(
        /\p{L}/gu,
      ) || []
    ).length;

  const suspiciousCount =
    (
      compactText.match(
        /[!$%&+\/<=>?@\\^{}]/g,
      ) || []
    ).length;

  const replacementCharacterCount =
    (
      compactText.match(
        /[\uFFFD\u0000]/g,
      ) || []
    ).length;

  const tokens = evaluatedText
    .split(/\s+/)
    .filter(Boolean);

  const symbolTokens = tokens.filter(
    token =>
      /^[^\p{L}\p{N}]+$/u.test(token),
  );

  const words =
    evaluatedText.match(/\p{L}{2,}/gu) || [];

  const wordCharacterCount =
    words.reduce(
      (sum, word) => sum + word.length,
      0,
    );

  const alphanumericRatio =
    alphanumericCount / characterCount;

  const letterRatio =
    letterCount / characterCount;

  const suspiciousRatio =
    suspiciousCount / characterCount;

  const replacementRatio =
    replacementCharacterCount /
    characterCount;

  const symbolTokenRatio =
    tokens.length > 0
      ? symbolTokens.length / tokens.length
      : 1;

  const wordCoverage =
    wordCharacterCount / characterCount;

  let score = 0;
  const reasons = [];

  if (
    characterCount <
    CONFIG.minimumCharacters
  ) {
    score += 4;
    reasons.push('too_little_text');
  }

  if (
    alphanumericRatio <
    CONFIG.minimumAlphanumericRatio
  ) {
    score += 2;
    reasons.push(
      'low_alphanumeric_ratio',
    );
  }

  if (
    suspiciousRatio >
    CONFIG.maximumSuspiciousRatio
  ) {
    score += 2;
    reasons.push(
      'many_suspicious_characters',
    );
  }

  if (
    symbolTokenRatio >
    CONFIG.maximumSymbolTokenRatio
  ) {
    score += 1;
    reasons.push('many_symbol_tokens');
  }

  if (
    wordCoverage <
    CONFIG.minimumWordCoverage
  ) {
    score += 1;
    reasons.push('low_word_coverage');
  }

  if (replacementCharacterCount > 0) {
    score +=
      replacementRatio > 0.01 ? 4 : 2;

    reasons.push(
      'invalid_or_replacement_characters',
    );
  }

  if (
    letterRatio < 0.35 &&
    suspiciousRatio > 0.06
  ) {
    score += 2;
    reasons.push(
      'probable_broken_font_mapping',
    );
  }

  return {
    requiresForcedOcr:
      score >=
      CONFIG.fallbackScoreThreshold,

    score,
    reasons,

    metrics: {
      rawCharacters: rawText.length,
      evaluatedCharacters:
        characterCount,
      tokens: tokens.length,
      alphanumericRatio:
        round(alphanumericRatio),
      letterRatio:
        round(letterRatio),
      suspiciousRatio:
        round(suspiciousRatio),
      symbolTokenRatio:
        round(symbolTokenRatio),
      wordCoverage:
        round(wordCoverage),
      replacementRatio:
        round(replacementRatio),
    },
  };
}

/*
 * Verarbeitung der n8n-Items
 */

const items = $input.all();

/*
 * WICHTIG:
 * Der Name muss exakt dem Node entsprechen,
 * der die PDF herunterlädt.
 */
const pdfItems =
  $('Code - slice PDF').all();

return items.map((item, index) => {
  const assessment =
    assessTextQuality(item.json);

  /*
   * Original-PDF auswählen.
   * Dein Workflow verarbeitet normalerweise
   * nur ein Dokument, deshalb ist Index 0
   * ein zulässiger Fallback.
   */
  const pdfItem =
    pdfItems[index] ?? pdfItems[0];

  /*
   * Wenn die Binary noch am aktuellen Item
   * hängt, diese verwenden. Andernfalls die
   * Binary aus "HTTP - fetch PDF" übernehmen.
   */
  const binary =
    item.binary?.data
      ? item.binary
      : pdfItem?.binary;

  if (!binary?.data) {
    throw new Error(
      `Item ${index}: Die Original-PDF wurde ` +
      `im Binary-Feld "data" nicht gefunden. ` +
      `Prüfe den Output des Nodes ` +
      `"HTTP - fetch PDF".`,
    );
  }

  return {
    json: {
      ...item.json,

      requiresForcedOcr:
        assessment.requiresForcedOcr,

      textQuality: assessment,
    },

    /*
     * Hier wird die PDF tatsächlich
     * an den nächsten Node weitergegeben.
     */
    binary,

    pairedItem: {
      item: index,
    },
  };
});

/**
 * n8n Code-Node: requiresVLM?
 *
 * Dieser Node wird nach der Forced-OCR-Ausführung aufgerufen.
 *
 * Ergebnis:
 *   requiresVLM: true
 *     OCR-Ergebnis ist grundsätzlich unbrauchbar.
 *     Aktuell: Dokument als failed markieren.
 *     Später: PaddleOCR-VL aufrufen.
 *
 *   requiresVLM: false
 *     OCR-Ergebnis kann weiterverarbeitet werden.
 */

const CONFIG = {
  minimumCharacters: 50,
  minimumAlphanumericRatio: 0.48,
  maximumSuspiciousRatio: 0.12,
  maximumSymbolTokenRatio: 0.30,
  minimumWordCoverage: 0.22,

  // Bewusst höher als beim ersten OCR-Gate:
  // VLM soll nur bei klar unbrauchbarer OCR ausgelöst werden.
  vlmScoreThreshold: 5,
};

function firstNonEmpty(values) {
  for (const value of values) {
    if (
      typeof value === 'string' &&
      value.trim() !== ''
    ) {
      return value;
    }
  }

  return '';
}

function decodeBasicHtmlEntities(text) {
  return text
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&nbsp;/gi, ' ');
}

function removeMarkdownStructure(text) {
  return text
    // HTML-Kommentare und Bildplatzhalter entfernen
    .replace(/<!--[\s\S]*?-->/g, ' ')

    // Markdown-Tabellentrennzeilen entfernen
    .replace(
      /^\s*\|?(?:\s*:?-{3,}:?\s*\|)+\s*$/gm,
      ' ',
    )

    // Markdown-Strukturzeichen entfernen
    .replace(/[|#*_`~]/g, ' ')

    // Leerzeichen vereinheitlichen
    .replace(/\s+/g, ' ')
    .trim();
}

function round(value) {
  return Math.round(value * 1000) / 1000;
}

function assessVlmRequirement(json) {
  const rawText = firstNonEmpty([
    json?.document?.md_content,
    json?.document?.text_content,
    json?.md_content,
    json?.text_content,
    json?.text,
  ]);

  /*
   * Forced OCR hat gar keinen Text geliefert.
   */
  if (!rawText) {
    return {
      requiresVLM: true,
      score: 10,
      status: 'failed_requires_vlm',
      reasons: ['forced_ocr_returned_no_text'],
      metrics: {
        rawCharacters: 0,
        evaluatedCharacters: 0,
      },
    };
  }

  const decodedText =
    decodeBasicHtmlEntities(rawText);

  const evaluatedText =
    removeMarkdownStructure(decodedText);

  const compactText =
    evaluatedText.replace(/\s/g, '');

  const characterCount = compactText.length;

  if (characterCount === 0) {
    return {
      requiresVLM: true,
      score: 10,
      status: 'failed_requires_vlm',
      reasons: ['forced_ocr_returned_no_evaluable_text'],
      metrics: {
        rawCharacters: rawText.length,
        evaluatedCharacters: 0,
      },
    };
  }

  const alphanumericCount =
    (
      compactText.match(
        /[\p{L}\p{N}]/gu,
      ) || []
    ).length;

  const letterCount =
    (
      compactText.match(
        /\p{L}/gu,
      ) || []
    ).length;

  const suspiciousCount =
    (
      compactText.match(
        /[!$%&+\/<=>?@\\^{}]/g,
      ) || []
    ).length;

  const replacementCharacterCount =
    (
      compactText.match(
        /[\uFFFD\u0000]/g,
      ) || []
    ).length;

  const tokens = evaluatedText
    .split(/\s+/)
    .filter(Boolean);

  const symbolTokens = tokens.filter(
    token =>
      /^[^\p{L}\p{N}]+$/u.test(token),
  );

  const words =
    evaluatedText.match(/\p{L}{2,}/gu) || [];

  const wordCharacterCount =
    words.reduce(
      (sum, word) => sum + word.length,
      0,
    );

  const alphanumericRatio =
    alphanumericCount / characterCount;

  const letterRatio =
    letterCount / characterCount;

  const suspiciousRatio =
    suspiciousCount / characterCount;

  const symbolTokenRatio =
    tokens.length > 0
      ? symbolTokens.length / tokens.length
      : 1;

  const wordCoverage =
    wordCharacterCount / characterCount;

  const replacementRatio =
    replacementCharacterCount /
    characterCount;

  let score = 0;
  const reasons = [];

  if (
    characterCount <
    CONFIG.minimumCharacters
  ) {
    score += 5;
    reasons.push(
      'forced_ocr_returned_too_little_text',
    );
  }

  if (
    alphanumericRatio <
    CONFIG.minimumAlphanumericRatio
  ) {
    score += 3;
    reasons.push(
      'forced_ocr_low_alphanumeric_ratio',
    );
  }

  if (
    suspiciousRatio >
    CONFIG.maximumSuspiciousRatio
  ) {
    score += 3;
    reasons.push(
      'forced_ocr_many_suspicious_characters',
    );
  }

  if (
    symbolTokenRatio >
    CONFIG.maximumSymbolTokenRatio
  ) {
    score += 2;
    reasons.push(
      'forced_ocr_many_symbol_tokens',
    );
  }

  if (
    wordCoverage <
    CONFIG.minimumWordCoverage
  ) {
    score += 2;
    reasons.push(
      'forced_ocr_low_word_coverage',
    );
  }

  if (replacementCharacterCount > 0) {
    score +=
      replacementRatio > 0.01 ? 5 : 3;

    reasons.push(
      'forced_ocr_contains_invalid_characters',
    );
  }

  /*
   * Typischer Zeichensalat:
   * wenige Buchstaben und gleichzeitig
   * ungewöhnlich viele Sonderzeichen.
   */
  if (
    letterRatio < 0.30 &&
    suspiciousRatio > 0.08
  ) {
    score += 4;
    reasons.push(
      'forced_ocr_probable_character_garbage',
    );
  }

  const requiresVLM =
    score >= CONFIG.vlmScoreThreshold;

  return {
    requiresVLM,
    score,

    status: requiresVLM
      ? 'failed_requires_vlm'
      : 'ocr_accepted',

    reasons,

    metrics: {
      rawCharacters: rawText.length,
      evaluatedCharacters: characterCount,
      tokens: tokens.length,
      alphanumericRatio:
        round(alphanumericRatio),
      letterRatio:
        round(letterRatio),
      suspiciousRatio:
        round(suspiciousRatio),
      symbolTokenRatio:
        round(symbolTokenRatio),
      wordCoverage:
        round(wordCoverage),
      replacementRatio:
        round(replacementRatio),
    },
  };
}

/*
 * Eingehende Docling-OCR-Ergebnisse
 */
const items = $input.all();

/*
 * Original-PDF erneut aus dem Download-Node holen.
 * Dadurch steht sie später auch für PaddleOCR-VL bereit.
 */
const pdfItems =
  $('Code - slice PDF').all();

return items.map((item, index) => {
  const assessment =
    assessVlmRequirement(item.json);

  const pdfItem =
    pdfItems[index] ?? pdfItems[0];

  const binary =
    item.binary?.data
      ? item.binary
      : pdfItem?.binary;

  if (!binary?.data) {
    throw new Error(
      `Item ${index}: Original-PDF im Binary-Feld ` +
      `"data" nicht gefunden.`,
    );
  }

  return {
    json: {
      ...item.json,

      requiresVLM:
        assessment.requiresVLM,

      vlmQualityAssessment:
        assessment,

      processingStatus:
        assessment.status,

      fallbackStage:
        assessment.requiresVLM
          ? 'paddleocr_vl_pending'
          : null,
    },

    binary,

    pairedItem: {
      item: index,
    },
  };
});

const response = $input.first().json;

const part =
  $('MySQL - claim one pending part').first().json;

const markdown =
  response?.document?.md_content
  ?? response?.md_content
  ?? response?.md
  ?? '';

const json =
  response?.document?.json_content
  ?? {};

const forcedOcrUsed =
  $('HTTP - call docling with forced OCR').isExecuted;

return [{
  json: {
    PartID: part.PartID,
    QueueID: part.QueueID,
    TextUUID: part.TextUUID,

    PartNumber: part.PartNumber,
    PageFrom: part.PageFrom,
    PageTo: part.PageTo,

    Extractor: forcedOcrUsed
      ? 'docling_ocr'
      : 'docling',

    DoclingJSON: JSON.stringify(json),
    DoclingMD: markdown,
    PaddleJSON: null
  }
}];

const item = $input.first();

const binaryProperties = Object.keys(item.binary ?? {});

if (binaryProperties.length === 0) {
  throw new Error('Keine Binärdatei für PaddleOCR-VL vorhanden');
}

const binaryPropertyName = binaryProperties.includes('data')
  ? 'data'
  : binaryProperties[0];

const fileBuffer = await this.helpers.getBinaryDataBuffer(
  0,
  binaryPropertyName
);

if (!fileBuffer?.length) {
  throw new Error('Die Binärdatei für PaddleOCR-VL ist leer');
}

return [
  {
    json: {
      ...item.json,
      PaddleFileBase64: fileBuffer.toString('base64'),
      PaddleFileType: 0,
    },
    binary: item.binary,
  },
];

const response = $input.first().json;

const part =
  $('MySQL - claim one pending part').first().json;

if (
  response?.errorCode !== undefined
  && Number(response.errorCode) !== 0
) {
  throw new Error(
    `PaddleOCR-VL Fehler ${response.errorCode}: `
    + `${response.errorMsg || 'Unbekannter Fehler'}`
  );
}

const layoutParsingResults =
  response?.result?.layoutParsingResults;

if (!Array.isArray(layoutParsingResults)) {
  throw new Error(
    'PaddleOCR-VL-Antwort enthält keine layoutParsingResults'
  );
}

function cleanText(value) {
  return String(value ?? '')
    .replace(/<img\b[^>]*>/gi, '')
    .replace(/<\/?div\b[^>]*>/gi, '')
    .replace(/\r\n?/g, '\n')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

/**
 * Erkennt eingebettete Bilder anhand typischer Base64-Signaturen.
 */
function isEmbeddedImage(value) {
  if (typeof value !== 'string') {
    return false;
  }

  const content = value.trim();

  return (
    /^data:image\//i.test(content)
    || /^\/9j\//.test(content)       // JPEG
    || /^iVBORw0KGgo/.test(content)  // PNG
    || /^R0lGOD/.test(content)       // GIF
    || /^UklGR/.test(content)        // WebP
    || /^Qk/.test(content)           // BMP
  );
}

/**
 * Diese Feldnamen enthalten typischerweise Bilddaten oder
 * Bildsammlungen. Die Normalisierung entfernt _, - und Großschreibung.
 */
const imageFieldNames = new Set([
  'image',
  'images',
  'img',
  'imgs',
  'inputimage',
  'inputimages',
  'outputimage',
  'outputimages',
  'imagebase64',
  'base64image',
  'imagebytes',
  'imageblob',
  'imagedata',
  'markdownimages',
]);

function normalizeFieldName(name) {
  return String(name ?? '')
    .toLowerCase()
    .replace(/[^a-z0-9]/g, '');
}

/**
 * Entfernt Bilder rekursiv, unabhängig davon, an welcher Stelle
 * Paddle sie in layoutParsingResults zurückgibt.
 */
function removeEmbeddedImages(value) {
  if (Array.isArray(value)) {
    for (let index = value.length - 1; index >= 0; index--) {
      if (isEmbeddedImage(value[index])) {
        value.splice(index, 1);
      } else {
        removeEmbeddedImages(value[index]);
      }
    }

    return value;
  }

  if (
    value === null
    || typeof value !== 'object'
  ) {
    return value;
  }

  for (const key of Object.keys(value)) {
    const child = value[key];
    const normalizedKey = normalizeFieldName(key);

    if (
      imageFieldNames.has(normalizedKey)
      || isEmbeddedImage(child)
    ) {
      delete value[key];
      continue;
    }

    removeEmbeddedImages(child);

    /*
     * Leere Bildcontainer nach der rekursiven Bereinigung entfernen.
     */
    if (
      imageFieldNames.has(normalizedKey)
      && (
        value[key] === null
        || (
          typeof value[key] === 'object'
          && Object.keys(value[key]).length === 0
        )
      )
    ) {
      delete value[key];
    }
  }

  return value;
}

/**
 * Tiefe JSON-kompatible Kopie erstellen.
 */
const cleanedLayoutParsingResults =
  JSON.parse(JSON.stringify(layoutParsingResults));

for (const page of cleanedLayoutParsingResults) {
  /*
   * Markdown-Text bereinigen.
   */
  if (
    page?.markdown
    && typeof page.markdown === 'object'
  ) {
    page.markdown.text =
      cleanText(page.markdown.text);
  } else if (typeof page?.markdown === 'string') {
    page.markdown = {
      text: cleanText(page.markdown),
    };
  }

  const blocks =
    page?.prunedResult?.parsing_res_list
    ?? page?.prunedResult?.parsingResList
    ?? page?.parsing_res_list
    ?? page?.parsingResList
    ?? [];

  if (!Array.isArray(blocks)) {
    continue;
  }

  for (const block of blocks) {
    const contentProperty =
      Object.prototype.hasOwnProperty.call(
        block,
        'block_content'
      )
        ? 'block_content'
        : Object.prototype.hasOwnProperty.call(
            block,
            'content'
          )
          ? 'content'
          : Object.prototype.hasOwnProperty.call(
              block,
              'text'
            )
            ? 'text'
            : 'block_content';

    const cleanedContent =
      cleanText(block?.[contentProperty]);

    block[contentProperty] = cleanedContent;

    const currentLabel = String(
      block?.block_label
      ?? block?.label
      ?? ''
    ).toLowerCase();

    /*
     * OCR-haltige Bildblöcke für den Chunker als Text kennzeichnen.
     * Das ursprüngliche Label bleibt erhalten.
     */
    if (
      ['image', 'picture'].includes(currentLabel)
      && cleanedContent
    ) {
      if (block.block_label !== undefined) {
        block.original_block_label =
          block.block_label;

        block.block_label = 'text';
      } else {
        block.original_label = block.label;
        block.label = 'text';
      }
    }
  }
}

/*
 * Jetzt sämtliche eingebetteten Bilder rekursiv entfernen,
 * insbesondere page.inputImage.
 */
removeEmbeddedImages(cleanedLayoutParsingResults);

const paddleText = cleanedLayoutParsingResults
  .map(page => {
    const markdownText =
      page?.markdown?.text;

    if (
      typeof markdownText === 'string'
      && markdownText.trim()
    ) {
      return markdownText;
    }

    const blocks =
      page?.prunedResult?.parsing_res_list
      ?? page?.prunedResult?.parsingResList
      ?? page?.parsing_res_list
      ?? page?.parsingResList
      ?? [];

    return Array.isArray(blocks)
      ? blocks
          .map(block =>
            block?.block_content
            ?? block?.content
            ?? block?.text
            ?? ''
          )
          .filter(Boolean)
          .join('\n\n')
      : '';
  })
  .filter(Boolean)
  .join('\n\n')
  .trim();

if (!paddleText) {
  throw new Error(
    'PaddleOCR-VL hat keinen Text erkannt'
  );
}

const compactPaddleResult = {
  schemaVersion: 1,
  layoutParsingResults:
    cleanedLayoutParsingResults,
};

const serializedPaddleResult =
  JSON.stringify(compactPaddleResult);

/*
 * Sicherheitsprüfung: Es dürfen keine bekannten Bildsignaturen
 * mehr im gespeicherten JSON vorkommen.
 */
if (
  /data:image\//i.test(serializedPaddleResult)
  || /\/9j\//.test(serializedPaddleResult)
  || /iVBORw0KGgo/.test(serializedPaddleResult)
  || /R0lGOD/.test(serializedPaddleResult)
) {
  throw new Error(
    'PaddleJSON enthält nach der Bereinigung weiterhin Bilddaten'
  );
}

return [{
  json: {
    PartID: part.PartID,
    QueueID: part.QueueID,
    TextUUID: part.TextUUID,

    PartNumber: part.PartNumber,
    PageFrom: part.PageFrom,
    PageTo: part.PageTo,

    Extractor: 'paddle_vl',

    DoclingJSON: null,
    DoclingMD: null,
    PaddleJSON: serializedPaddleResult
  }
}];

const item = $input.first();

if (!item.binary?.data) {
  throw new Error('PDF im Binary-Feld "data" nicht gefunden');
}

const buffer = await this.helpers.getBinaryDataBuffer(
  0,
  'data'
);

const { PDFDocument } = require('pdf-lib');

const pdf = await PDFDocument.load(buffer, {
  ignoreEncryption: false,
});

const pages = pdf.getPageCount();

return [
  {
    json: {
      pages,
      fileSizeBytes: buffer.length,
    },
    binary: item.binary,
  },
];

const source =
  $('MySQL - claim one pending row').first().json;

const input = $input.first();
const totalPages = Number(input.json.pages);

const MAX_PAGES_PER_PART = 50;

if (!Number.isInteger(totalPages) || totalPages < 1) {
  throw new Error(
    `Ungültige PDF-Seitenzahl: ${input.json.pages}`
  );
}

const totalParts =
  Math.ceil(totalPages / MAX_PAGES_PER_PART);

const parts = [];

for (
  let partNumber = 1;
  partNumber <= totalParts;
  partNumber++
) {
  const pageFrom =
    (partNumber - 1) * MAX_PAGES_PER_PART + 1;

  const pageTo =
    Math.min(
      partNumber * MAX_PAGES_PER_PART,
      totalPages
    );

  parts.push({
    json: {
      QueueID: source.QueueID,
      TextUUID: source.TextUUID,
      Filepath: source.Filepath,

      PartNumber: partNumber,
      PageFrom: pageFrom,
      PageTo: pageTo,

      PageCount: pageTo - pageFrom + 1,
      TotalPages: totalPages,
      TotalParts: totalParts
    },

    // PDF hier nicht mehr vervielfältigen.
    // Der Part-Worker lädt sie später anhand Filepath neu.
    pairedItem: {
      item: 0
    }
  });
}

return parts;

const source =
  $('MySQL - claim one pending row').first().json;

const parts =
  $('Code - create extraction parts').all();

return [{
  json: {
    QueueID: source.QueueID,
    TextUUID: source.TextUUID,
    TotalParts: parts.length
  }
}];

const item = $input.first();

const part =
  $('MySQL - claim one pending part').first().json;

if (!item.binary?.data) {
  throw new Error(
    'PDF im Binary-Feld "data" nicht gefunden'
  );
}

const sourceBuffer =
  await this.helpers.getBinaryDataBuffer(
    0,
    'data'
  );

const { PDFDocument } = require('pdf-lib');

const sourcePdf =
  await PDFDocument.load(sourceBuffer);

const totalPages =
  sourcePdf.getPageCount();

const pageFrom =
  Number(part.PageFrom);

const pageTo =
  Number(part.PageTo);

if (
  !Number.isInteger(pageFrom) ||
  !Number.isInteger(pageTo) ||
  pageFrom < 1 ||
  pageTo < pageFrom ||
  pageTo > totalPages
) {
  throw new Error(
    `Ungültiger Seitenbereich ${pageFrom}-${pageTo}; ` +
    `PDF enthält ${totalPages} Seiten`
  );
}

const partPages =
  pageTo - pageFrom + 1;

if (partPages > 50) {
  throw new Error(
    `Safety Limit verletzt: ${partPages} Seiten`
  );
}

const targetPdf =
  await PDFDocument.create();

/*
 * ENTSCHEIDEND:
 * Array von pdf-lib erzeugen lassen.
 *
 * Nicht selbst mit [], Array.from() etc. erzeugen,
 * weil n8n Task Runner und pdf-lib unterschiedliche
 * JavaScript Realms verwenden.
 */
const allPageIndices =
  sourcePdf.getPageIndices();

const pageIndices =
  allPageIndices.slice(
    pageFrom - 1,
    pageTo
  );

if (pageIndices.length !== partPages) {
  throw new Error(
    `Page-Slice inkonsistent: ` +
    `${pageIndices.length} statt ${partPages}`
  );
}

const copiedPages =
  await targetPdf.copyPages(
    sourcePdf,
    pageIndices
  );

for (const page of copiedPages) {
  targetPdf.addPage(page);
}

const bytes =
  await targetPdf.save();

const outputBuffer =
  Buffer.from(bytes);

const binaryData =
  await this.helpers.prepareBinaryData(
    outputBuffer,
    `part-${part.PartNumber}-pages-${pageFrom}-${pageTo}.pdf`,
    'application/pdf'
  );

return [{
  json: {
    PartID: part.PartID,
    QueueID: part.QueueID,
    TextUUID: part.TextUUID,

    PartNumber: part.PartNumber,

    PageFrom: pageFrom,
    PageTo: pageTo,

    PartPages: partPages,
    SourcePages: totalPages,

    FirstPdfIndex:
      pageIndices[0],

    LastPdfIndex:
      pageIndices[pageIndices.length - 1],

    SourceBytes:
      sourceBuffer.length,

    PartBytes:
      outputBuffer.length
  },

  binary: {
    data: binaryData
  }
}];

